<h1>Website media library</h1><p>Upload tenant-owned images, copy reusable media IDs, and set public visibility only for assets intended for anonymous pages.</p><form data-media-upload method="post" enctype="multipart/form-data" action="<?= site_url('tenant/website/media/upload') ?>"><?= csrf_field() ?><input type="file" name="file" accept="image/jpeg,image/png,image/webp" required><select name="category"><?php foreach(config('WebsiteMedia')->allowedCategories as $category): ?><option><?= esc($category) ?></option><?php endforeach ?></select><select name="visibility"><option>private</option><option>public</option></select><button>Upload image</button><progress data-upload-progress max="100" value="0" hidden></progress><output data-upload-message></output></form>
<div class="card-grid"><?php foreach($mediaFiles as $file): ?><article class="editorial-card"><div><strong><?= esc($file['original_name']) ?></strong><p>ID <code><?= esc($file['id']) ?></code> — <?= esc($file['category']) ?> — <?= esc($file['visibility']) ?></p><button type="button" data-copy-media-id="<?= esc($file['id']) ?>">Copy media ID</button></div></article><?php endforeach ?></div><script src="<?= base_url('assets/js/website-media-library.js') ?>" defer></script><?= $this->endSection() ?>
